import { Component, OnInit, NgZone, signal, inject } from '@angular/core';
import { FormGroup, FormBuilder, Validators, ReactiveFormsModule } from '@angular/forms';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { AuthenticationService } from '../../userservices/authentication.service';
import { first } from 'rxjs/operators';
import { AlertService } from '../../../utils/alert/alert.service';
import { AlertComponent } from '../../../utils/alert/alert/alert.component';

@Component({
  selector: 'app-signup',
  imports: [RouterModule, AlertComponent, ReactiveFormsModule],
  templateUrl: './signup.component.html',
  styleUrls: ['./signup.component.css']
})
export class SignupComponent implements OnInit {

  private formBuilder = inject(FormBuilder);
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private authenticationService = inject(AuthenticationService);
  private alertService =inject(AlertService);
  private zone = inject(NgZone);

  loading = signal<boolean>(false);
  submitted = signal<boolean>(false);

  signupForm: FormGroup;
  
  returnUrl: string | null = null;

  constructor() {
    this.signupForm = this.formBuilder.group({
      firstname: ['', Validators.required],
      lastname: ['', Validators.required],
      email: ['', [Validators.email, Validators.required]],
      password: ['', Validators.required],
      mobilenumber: ['', [Validators.required, Validators.minLength(10)]],
      address: ['', Validators.required],
      country: ['', Validators.required]
    });
   }

  ngOnInit() {
    
    this.returnUrl = this.route.snapshot.queryParams['returnUrl'] || '/home';
  }

  get f() { return this.signupForm?.controls; };

  onSubmit() {
    this.submitted.set(true);

    // stop here if form is invalid
    if (this.signupForm?.invalid) {
      return;
    }
    this.loading.set(true);

    this.authenticationService.signUp(this.f?.['firstname'].value, this.f?.['lastname'].value, this.f?.['email'].value, this.f?.['password'].value, this.f?.['mobilenumber'].value, this.f?.['address'].value, this.f?.['country'].value)
      .pipe(first())
      .subscribe({
        next: (data) => {
          if (data['success']) {
            this.alertService.success(data['ops']);
            this.zone.run(() => {
              this.router.navigate([this.returnUrl]);
            })
          } else {
            this.alertService.error(data['ops']);
            this.loading.set(false);
          }
        },
        error: (error) => {
          this.alertService.error(error);
          this.loading.set(false);
        },
        complete: () => { this.loading.set(false) }
      })
  }
}
